using Npgsql;
using NpgsqlTypes;
using SCOPX.Infrastructure.Audit;
namespace SCOPX.Infrastructure.Reports;
public sealed class NpgsqlReportRepository(string connectionString) : IReportRepository
{
 private static async Task SetTenant(NpgsqlConnection c,NpgsqlTransaction t,Guid h,CancellationToken ct){await using var cmd=new NpgsqlCommand("SELECT set_config('scopx.hospital_id', @h, true)",c,t);cmd.Parameters.AddWithValue("h",NpgsqlDbType.Text,h.ToString());await cmd.ExecuteNonQueryAsync(ct);}
 private const string Columns="id,hospital_id,procedure_id,report_version,status,report_body,created_at,updated_at";
 private static ProcedureReportRecord Read(NpgsqlDataReader r)=>new(r.GetGuid(0),r.GetGuid(1),r.GetGuid(2),r.GetInt32(3),r.GetString(4),r.GetString(5),r.GetFieldValue<DateTimeOffset>(6),r.GetFieldValue<DateTimeOffset>(7));
 public async Task<IReadOnlyList<ProcedureReportRecord>> ListForProcedureAsync(Guid h,Guid p,CancellationToken ct=default){await using var c=new NpgsqlConnection(connectionString);await c.OpenAsync(ct);await using var t=await c.BeginTransactionAsync(ct);await SetTenant(c,t,h,ct);await using var cmd=new NpgsqlCommand($"SELECT {Columns} FROM procedure_reports WHERE hospital_id=@h AND procedure_id=@p ORDER BY report_version DESC LIMIT 100",c,t);cmd.Parameters.AddWithValue("h",h);cmd.Parameters.AddWithValue("p",p);await using var r=await cmd.ExecuteReaderAsync(ct);var rows=new List<ProcedureReportRecord>();while(await r.ReadAsync(ct))rows.Add(Read(r));await t.CommitAsync(ct);return rows;}
 public async Task<ProcedureReportRecord?> GetAsync(Guid h,Guid id,CancellationToken ct=default){await using var c=new NpgsqlConnection(connectionString);await c.OpenAsync(ct);await using var t=await c.BeginTransactionAsync(ct);await SetTenant(c,t,h,ct);await using var cmd=new NpgsqlCommand($"SELECT {Columns} FROM procedure_reports WHERE hospital_id=@h AND id=@id LIMIT 1",c,t);cmd.Parameters.AddWithValue("h",h);cmd.Parameters.AddWithValue("id",id);await using var r=await cmd.ExecuteReaderAsync(ct);var row=await r.ReadAsync(ct)?Read(r):null;await t.CommitAsync(ct);return row;}
 public async Task<ProcedureReportRecord?> CreateDraftAsync(Guid h,Guid actorUserId,Guid p,string body,CancellationToken ct=default){const string sql="INSERT INTO procedure_reports(hospital_id,procedure_id,report_body,status) SELECT @h,id,@body,'draft' FROM procedures WHERE hospital_id=@h AND id=@p RETURNING id";await using var c=new NpgsqlConnection(connectionString);await c.OpenAsync(ct);await using var t=await c.BeginTransactionAsync(ct);await SetTenant(c,t,h,ct);await using var cmd=new NpgsqlCommand(sql,c,t);cmd.Parameters.AddWithValue("h",h);cmd.Parameters.AddWithValue("p",p);cmd.Parameters.AddWithValue("body",NpgsqlDbType.Text,body);var result=await cmd.ExecuteScalarAsync(ct);if(result is not Guid id){await t.CommitAsync(ct);return null;}
 await NpgsqlAuditEventWriter.WriteAsync(c,t,h,actorUserId,"report.draft_created","procedure_report",id,new{operation="create_draft"},ct);
 await t.CommitAsync(ct);return await GetAsync(h,id,ct);}
 public async Task<bool> UpdateDraftAsync(Guid h,Guid actorUserId,Guid id,string body,CancellationToken ct=default){const string sql="UPDATE procedure_reports SET report_body=@body,updated_at=now() WHERE hospital_id=@h AND id=@id AND status='draft' AND signed_at IS NULL";await using var c=new NpgsqlConnection(connectionString);await c.OpenAsync(ct);await using var t=await c.BeginTransactionAsync(ct);await SetTenant(c,t,h,ct);await using var cmd=new NpgsqlCommand(sql,c,t);cmd.Parameters.AddWithValue("h",h);cmd.Parameters.AddWithValue("id",id);cmd.Parameters.AddWithValue("body",NpgsqlDbType.Text,body);var n=await cmd.ExecuteNonQueryAsync(ct);if(n==1)await NpgsqlAuditEventWriter.WriteAsync(c,t,h,actorUserId,"report.draft_updated","procedure_report",id,new{operation="update_draft"},ct);await t.CommitAsync(ct);return n==1;}
 public async Task<bool> SubmitReviewAsync(Guid h,Guid actorUserId,Guid id,CancellationToken ct=default){const string sql="UPDATE procedure_reports SET status='review',updated_at=now() WHERE hospital_id=@h AND id=@id AND status='draft' AND length(trim(report_body))>0 AND signed_at IS NULL";await using var c=new NpgsqlConnection(connectionString);await c.OpenAsync(ct);await using var t=await c.BeginTransactionAsync(ct);await SetTenant(c,t,h,ct);await using var cmd=new NpgsqlCommand(sql,c,t);cmd.Parameters.AddWithValue("h",h);cmd.Parameters.AddWithValue("id",id);var n=await cmd.ExecuteNonQueryAsync(ct);if(n==1)await NpgsqlAuditEventWriter.WriteAsync(c,t,h,actorUserId,"report.submitted_for_review","procedure_report",id,new{operation="submit_review"},ct);await t.CommitAsync(ct);return n==1;}
}
